package com.chronos.education.grade.model;
import com.chronos.model.pojo.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Getter @Setter @NoArgsConstructor @Table(name="edu_gradebook_student",uniqueConstraints=@UniqueConstraint(name="uk_edu_gradebook_student",columnNames={"gradebook_id","student_id"}))
public class GradebookStudent extends BaseEntity { @Column(name="gradebook_id",nullable=false,length=64) private String gradebookId; @Column(name="student_id",nullable=false,length=64) private String studentId; @Column(name="student_no",nullable=false,length=64) private String studentNo; @Column(name="student_name",nullable=false,length=128) private String studentName; @Column(name="administrative_class_id",length=64) private String administrativeClassId; @Column(name="enrollment_status",nullable=false,length=24) private String enrollmentStatus; @Column(name="source_member_id",nullable=false,length=64) private String sourceMemberId; @Column(name="enrolled_at") private LocalDateTime enrolledAt; @Column(name="withdrawn_at") private LocalDateTime withdrawnAt; @Column(name="snapshot_version",nullable=false) private Integer snapshotVersion=1; @Column(name="snapshot_hash",nullable=false,length=64) private String snapshotHash; }
